    "OrderSubCategory" = "ORDER_STATUS, CANCEL_ORDER, CHANGE_ORDER, PLACE_ORDER, ORDER_CONFIRMATION, PRE_ORDER, DUPLICATE_ORDER, GENERAL_ORDER_QUESTION"
    "ReturnsSubCategory" = "RETURN_REQUEST, RETURN_STATUS, RETURN_ELIGIBILITY, RETURN_SHIPPING, REFUND_REQUEST, REFUND_PENDING, REFUND_AMOUNT, REFUND_AFTER_CANCELLATION_OR_RETURN"
    "ProductProblemSubCategory" = "DAMAGED_PRODUCT, DEFECTIVE_OR_NOT_WORKING, WRONG_PRODUCT, MISSING_ITEM_OR_COMPONENT, REPLACEMENT_REQUEST, PRODUCT_QUALITY_PROBLEM, OTHER_PRODUCT_PROBLEM"
    "PaymentSubCategory" = "PAYMENT_FAILED, PAYMENT_DECLINED, PAYMENT_VERIFICATION, UNEXPECTED_CHARGE, CHARGE_OR_BILLING_PROBLEM, CARD_CHARGED, GENERAL_PAYMENT_PROBLEM"
    "PrimeMembershipSubCategory" = "GENERAL_PRIME_QUESTION, PRIME_MEMBERSHIP_OR_BENEFITS, PRIME_TRIAL, PRIME_RENEWAL, CANCEL_PRIME, PRIME_MEMBERSHIP_CHARGE, PRIME_DELIVERY_BENEFIT"
