    "AmazonDevicesSubCategory" = "ECHO_PROBLEM, ALEXA_PROBLEM, FIRE_TV_OR_FIRE_TV_STICK_PROBLEM, DEVICE_SETUP, DEVICE_CONNECTIVITY, DEVICE_NOT_WORKING, GENERAL_DEVICE_QUESTION"
    "KindleSubCategory" = "KINDLE_OR_READING_GENERAL, KINDLE_OR_EBOOK_ISSUE, KINDLE_BOOK_PURCHASE_OR_PRICING, KINDLE_BOOK_DOWNLOAD, KINDLE_BOOK_ACCESS, KINDLE_DEVICE_PROBLEM"
    "AmazonPaySubCategory" = "AMAZON_PAY_PAYMENT_OR_TRANSACTION, AMAZON_PAY_BALANCE, AMAZON_PAY_CASHBACK_OR_REWARDS, AMAZON_PAY_REFUND, AMAZON_PAY_ACCOUNT, AMAZON_PAY_FRAUD_OR_SUSPICIOUS_TRANSACTION"
