    "AddressSubCategory" = "ADDRESS_PROBLEM_OR_CHANGE, ADD_OR_REMOVE_ADDRESS, WRONG_DELIVERY_ADDRESS, DELIVERY_LOCATION_OR_SAFE_PLACE, DELIVERY_PREFERENCE"
    "PromotionsSubCategory" = "PROMOTION_OR_DISCOUNT, COUPON_PROBLEM, DISCOUNT_NOT_APPLIED, OFFER_ELIGIBILITY, CASHBACK_OR_PROMOTIONAL_OFFER"
    "GiftCardSubCategory" = "GIFT_CARD_PURCHASE, GIFT_CARD_REDEMPTION, GIFT_CARD_BALANCE, GIFT_CARD_NOT_RECEIVED, GIFT_CARD_NOT_WORKING, GIFT_CARD_CHARGE_OR_PAYMENT"
    "MarketplaceSubCategory" = "THIRD_PARTY_SELLER_PROBLEM, SELLER_COMMUNICATION, SELLER_ORDER_OR_DELIVERY, SELLER_RETURN_OR_REFUND, SELLER_ACCOUNT, SELLER_FRAUD_OR_COUNTERFEIT"
    "ProductInformationSubCategory" = "PRODUCT_PRICE_OR_PRICING, PRODUCT_AVAILABILITY, PRODUCT_INFORMATION, PRODUCT_SPECIFICATION, PRICE_DIFFERENCE_OR_PRICE_CHANGE, GENERAL_PRODUCT_QUESTION"
    "ShippingSubCategory" = "DAMAGED_PACKAGE, OPEN_OR_TAMPERED_PACKAGE, PACKAGING_PROBLEM, SHIPPING_CARRIER_PROBLEM, GENERAL_LOGISTICS_PROBLEM"
    "CustomerServiceSubCategory" = "POOR_CUSTOMER_SERVICE, NO_OR_DELAYED_RESPONSE, REPEATED_CONTACT, UNRESOLVED_ISSUE, GENERAL_SERVICE_COMPLAINT, PRAISE_OR_APPRECIATION"
    "PrivacySubCategory" = "ACCOUNT_SECURITY, SUSPICIOUS_ACTIVITY, UNAUTHORIZED_ACCESS, FRAUD_CONCERN, PERSONAL_INFORMATION_CONCERN, SECURITY_OR_VERIFICATION_PROBLEM"
    "GeneralInformationSubCategory" = "GENERAL_AMAZON_QUESTION, GENERAL_INFORMATION, GENERAL_COMPLAINT, FEEDBACK, PRAISE_OR_APPRECIATION, SOCIAL_OR_CONVERSATIONAL, OTHER_NON_ACTIONABLE_MESSAGE"
}

foreach ($key in $enums.Keys) {
    $vals = $enums[$key]
    $content = "package com.supportiq.model.intent;`n`npublic enum $key implements SubCategory {`n    " + $vals.Replace(", ", ",`n    ") + "`n}"
    Set-Content -Path "$baseDir\$key.java" -Value $content -Encoding UTF8
}

$subCategoryInterface = "package com.supportiq.model.intent;`n`npublic interface SubCategory {`n    String name();`n}"
Set-Content -Path "$baseDir\SubCategory.java" -Value $subCategoryInterface -Encoding UTF8

$mainCategoryEnum = "package com.supportiq.model.intent;`n`npublic enum MainCategory {`n    DELIVERY_AND_TRACKING,`n    ORDER_MANAGEMENT,`n    RETURNS_AND_REFUNDS,`n    PRODUCT_PROBLEM,`n    PAYMENT_AND_BILLING,`n    PRIME_MEMBERSHIP,`n    PRIME_VIDEO_AND_DIGITAL_CONTENT,`n    AMAZON_DEVICES,`n    KINDLE_AND_READING,`n    AMAZON_PAY,`n    ACCOUNT_AND_LOGIN,`n    ADDRESS_AND_DELIVERY_PREFERENCES,`n    PROMOTIONS_AND_DISCOUNTS,`n    GIFT_CARDS,`n    MARKETPLACE_AND_SELLERS,`n    PRODUCT_INFORMATION_AND_PRICING,`n    SHIPPING_PACKAGING_AND_LOGISTICS,`n    CUSTOMER_SERVICE_EXPERIENCE,`n    PRIVACY_AND_SECURITY,`n    GENERAL_INFORMATION_AND_NON_SUPPORT`n}"
Set-Content -Path "$baseDir\MainCategory.java" -Value $mainCategoryEnum -Encoding UTF8
